// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title MessageQueueConsumer
 * @notice Processes cross-chain messages from a Kubernetes-hosted relayer service.
 *         Messages are ABI-encoded off-chain and submitted as calldata.
 *         The relayer signs message batches; this contract verifies and executes.
 */
contract MessageQueueConsumer is Ownable, ReentrancyGuard {

    struct Message {
        address sender;
        address target;
        uint256 value;
        uint256 nonce;
        bytes payload;
    }

    mapping(bytes32 => bool) public processedMessages;
    mapping(address => uint256) public nonces;
    address public relayer;
    uint256 public messageGasLimit;

    event MessageProcessed(bytes32 indexed messageId, address indexed target, bool success);
    event RelayerUpdated(address indexed oldRelayer, address indexed newRelayer);

    constructor(address _relayer, uint256 _gasLimit) {
        require(_relayer != address(0), "Invalid relayer");
        relayer = _relayer;
        messageGasLimit = _gasLimit;
    }

    function setRelayer(address _newRelayer) external onlyOwner {
        require(_newRelayer != address(0), "Invalid relayer");
        emit RelayerUpdated(relayer, _newRelayer);
        relayer = _newRelayer;
    }

    function setGasLimit(uint256 _gasLimit) external onlyOwner {
        require(_gasLimit >= 21000 && _gasLimit <= 10_000_000, "Invalid gas limit");
        messageGasLimit = _gasLimit;
    }

    /**
     * @notice Decodes and validates a message batch from the relayer.
     * @dev The encoding format from the K8s relayer uses a compact representation:
     *      [uint16 msgCount][per message: address sender (20b) | address target (20b) | 
     *       uint256 value (32b) | uint256 nonce (32b) | uint16 payloadLen | bytes payload]
     *      followed by a 65-byte ECDSA signature over keccak256 of the raw batch data.
     */
    function processBatch(bytes calldata batchData) external nonReentrant {
        require(batchData.length >= 67, "Batch too short"); // min: 2 (count) + 65 (sig)

        // Extract signature (last 65 bytes)
        bytes calldata rawMessages = batchData[:batchData.length - 65];
        bytes calldata signature = batchData[batchData.length - 65:];

        // Verify relayer signature
        bytes32 batchHash = keccak256(rawMessages);
        require(_verifySignature(batchHash, signature), "Invalid signature");

        // Parse message count
        uint16 msgCount = uint16(bytes2(rawMessages[:2]));
        require(msgCount > 0 && msgCount <= 50, "Invalid message count");

        uint256 offset = 2;

        for (uint16 i = 0; i < msgCount; i++) {
            require(offset + 106 <= rawMessages.length, "Truncated message"); // 20+20+32+32+2 = 106 min

            Message memory msg_ = _decodeMessage(rawMessages, offset);
            offset += 106 + msg_.payload.length;

            _executeMessage(msg_);
        }
    }

    function _decodeMessage(bytes calldata data, uint256 offset) internal pure returns (Message memory msg_) {
        msg_.sender = address(bytes20(data[offset:offset+20]));
        offset += 20;

        msg_.target = address(bytes20(data[offset:offset+20]));
        offset += 20;

        msg_.value = uint256(bytes32(data[offset:offset+32]));
        offset += 32;

        msg_.nonce = uint256(bytes32(data[offset:offset+32]));
        offset += 32;

        // Read payload length as uint16 from compact encoding
        uint16 payloadLen = uint16(bytes2(data[offset:offset+2]));
        offset += 2;

        // The payload bytes - note: we trust the declared length from the signed data
        if (payloadLen > 0) {
            msg_.payload = data[offset:offset+payloadLen];
        }

        return msg_;
    }

    function _executeMessage(Message memory msg_) internal {
        bytes32 messageId = keccak256(abi.encode(
            msg_.sender, msg_.target, msg_.value, msg_.nonce, keccak256(msg_.payload)
        ));

        require(!processedMessages[messageId], "Already processed");
        require(msg_.nonce == nonces[msg_.sender], "Invalid nonce");

        processedMessages[messageId] = true;
        nonces[msg_.sender]++;

        // Execute the message call with gas limit
        bool success;
        if (msg_.payload.length > 0) {
            (success, ) = msg_.target.call{value: msg_.value, gas: messageGasLimit}(msg_.payload);
        } else {
            (success, ) = msg_.target.call{value: msg_.value, gas: messageGasLimit}("");
        }

        emit MessageProcessed(messageId, msg_.target, success);
    }

    function _verifySignature(bytes32 hash, bytes calldata signature) internal view returns (bool) {
        require(signature.length == 65, "Invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            let sigStart := signature.offset
            r := calldataload(sigStart)
            s := calldataload(add(sigStart, 32))
            v := byte(0, calldataload(add(sigStart, 64)))
        }

        if (v < 27) v += 27;
        require(v == 27 || v == 28, "Invalid v value");

        // Prevent signature malleability
        require(uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0, "Invalid s value");

        bytes32 ethSignedHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash));
        address recovered = ecrecover(ethSignedHash, v, r, s);

        return recovered == relayer && recovered != address(0);
    }

    /**
     * @notice Allows computing a message ID off-chain for tracking
     */
    function computeMessageId(
        address sender,
        address target, 
        uint256 value,
        uint256 nonce_,
        bytes calldata payload
    ) external pure returns (bytes32) {
        return keccak256(abi.encode(sender, target, value, nonce_, keccak256(payload)));
    }

    receive() external payable {}

    function withdrawStuckFunds(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        (bool success, ) = to.call{value: amount}("");
        require(success, "Transfer failed");
    }
}
